(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mi"] = {"ui":{"skip":"Peke ki ngā ihirangi","back":"← Hoki ki AI-gile","lang.button":"Reo: {name}","lang.dialog":"Kōwhiria he reo","lang.search":"Rapua ngā reo","lang.none":"Kāore he reo e ōrite","lang.notYet":"Kāore anō kia whakamāoritia ki te reo {name}","theme.aria":"Whakawhiti i waenga i te āhua mārama me te āhua pōuri","theme.toLight":"Whakawhiti ki te āhua mārama","theme.toDark":"Whakawhiti ki te āhua pōuri","index.title":"AI-gile: tō rōpū hanga AI i runga i te papa kotahi","index.description":"He papa kanban a AI-gile mō ngā rōpū waehere AI. Ka mahi rātou i a koe e moe ana; ka toe māu he puranga poto: he mea hei whakatau, hei whakamātau, hei whakaae.","hero.logoAlt":"Tohu papa AI-gile","hero.h1.html":"Tō rōpū hanga AI, i runga i te papa&nbsp;kotahi.","hero.alpha":"🐣 Pre-alpha kati","hero.alphaTitle":"Tōmua, kāore anō kia oti: ngā mihi mō tō whakamātau!","hero.lede":"Ka hanga rātou i a koe e moe ana. Ka ara koe ki te puranga poto kotahi: ētahi pātai, ētahi mea hei whakamātau, tētahi taimana waiporoporo e rua rānei. Pāwhiri, whakaae, hoki ki tō kawhe.","dl.windows":"Taupānga Windows","dl.browser":"Whakahaerehia i tō pūtirotiro","dl.soon":"Tērā ake nei","dl.notify":"🔔 Whakamōhio mai ina tuwhera","dl.notifySmall":"Alpha, beta rānei","hero.secondary":"Agile, engari kāore te rōpū e hiahia ana ki te kawhe tū. (Heoi ka mahi tonu rātou i ngā stand-up.)","pitch.h2":"AI-gile i te maha o ngā kupu e hiahia ana koe","pitch.lede":"Kōwhiria te roa, mai i te kupu kotahi ki te 144. He whakaahuatanga motuhake ia roa, i tuhia mō taua rahi. Toia te kaiwhakahaere, whakamahia rānei ngā pātuhi pere.","pitch.rangeLabel":"Te roa i ngā kupu","pitch.dice":"🎲 tētahi atu putanga","pitch.words.other":"{n} kupu","pitch.words.one":"{n} kupu","pitch.letters.other":"{n} reta","pitch.letters.one":"{n} reta","pitch.chars.other":"{n} tohu","pitch.chars.one":"{n} tohu","count.line.html.other":"E {n} ngā kāri kei te papa i tēnei wā","count.line.html.one":"E {n} ngā kāri kei te papa i tēnei wā","features.aria":"Āna mahi","f.pile.h":"Te puranga kotahi mōu","f.pile.html":"<b>Māu</b> kei konei ngā mea katoa e tatari ana ki a koe, puta noa i ngā kaupapa katoa: ngā pātai, ngā mea hei whakamātau, ngā mahi mā te tangata anake. Ka mea tō rārangi he aha te mea e whai ake nei, me te roa e pau ai.","f.sleep.h":"Ngā rōpū e mahi ana i a koe e moe ana","f.sleep.p":"He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiritia he kōrero ki tētahi kāri, ka oho te rōpū, ka mahi, ka hoatu anō me ngā hikoi e ngāwari ana mā te tangata ngenge.","f.tester.h":"Ka tirotiro tuatahi he kaiwhakamātau AI","f.tester.p":"I mua i te taenga ki a koe, ka whai te kaiwhakamātau i ngā hikoi i runga i tētahi kape o te taupānga, ka whakaatu i tāna i kite ai, me te tānga mata. Tirohia wawe ngā mea i ngata, ka whakaae mā te pāwhiri kotahi.","f.proof.h":"He taunakitanga, ehara i te oati","f.proof.p":"Ka whakaatu ia tuku i ngā mea kua rerekē: ngā kōnae, te rerekētanga, ngā tānga mata. Kāore e tika kia whakatuwheratia ia taupānga hei tiro mēnā kua oti.","f.chat.h":"Kōrero ki ō kaihautū","f.chat.p":"He kōrero-ara pērā i a Discord: kotahi te tohu mō ia kaupapa, he taimana waiporoporo mō ngā mea e hiahia ana ki a koe. Tukuna he whakaaro ki tētahi kaihautū; ka huri ia hei kāri me tētahi mahere, me tētahi pātene ✅ Haere.","f.tidy.h":"Ka noho ia i te tōtika","f.tidy.p":"Ka whakakotahi ngā kāri e hāngai ana, ka whakatikahia ngā taitara rangirua, ā, ka tiaki te tirotiro tohu i te waehere kia kōmaki. Torutoru ake ngā mea hei huri atu ki, torutoru ake ngā mea hei whakaaro.","f.private.h":"Nōu, i runga i tō rorohiko","f.private.li1":"Ka rere te papa i runga i tō ake rorohiko, ā, ko koe anake tāna e whakautu ai.","f.private.li2":"He hunahuna ngā karere tūmataiti i waenga i ngā tāngata, mai i tētahi pito ki tētahi.","f.private.li3":"Kāore he kāute, kāore he kaiwhai, kāore he pihikete.","f.lang.h":"I tō reo","f.lang.p":"Neke atu i te 120 ngā reo, mai i te Tati, te Wēra me te Hapani ki te kaipahua, ki a Yoda me te Klingon, me tētahi whakawhiti tere ki te reo Ingarihi mō ngā kupu a te kaiwhakawhanake.","tl.aria":"Rārangi wā mai i te kōrero tuatahi ki te mahere","tl.h2":"Mai i te kōrero tuatahi ki te mea e haere ake nei","tl.lede":"He rā me ngā wā tūturu, i tō ake rohe wā. Whai muri i tēnei rā he mahere, kāore he rā i oatitia.","tl.today":"Tēnei rā","tl.planned":"kua whakaritea","tl.cards.other":"{n} kāri","tl.cards.one":"{n} kāri","join.h2":"Haere mai ki roto","join.lede":"Kei te hangaia a AI-gile e tētahi tangata iti me te tini o ngā kaiwhakahaere manawanui. He tūmataiti i tēnei wā, i te alpha kati me ngā hoa. Kei te hiahia koe ki te whakamātau ina tuwhera?","join.btn":"Tohua tō aro","join.small":"Ka īmēra atu mātou, kāore atu","footer.tag":"AI-gile. Kāore he kaiwhai, kāore he pihikete, kāore he kawhe tū.","footer.licence":"Raihana pakihi","footer.status":"Tūnga","form.sending":"E tuku ana…","form.failed":"Kāore i whai hua: whakamātauria anō a muri ake nei.","form.offline":"Kāore i taea te toro atu ki a AI-gile: whakamātauria anō a muri ake nei.","interest.title":"AI-gile: whakamōhiotia mai ina tuwhera te alpha","interest.description":"Waihotia tō īmēra kia mōhio koe ina tuwhera te alpha kati, te beta rānei o AI-gile.","interest.h1":"🔔 Whakamōhio mai ina tuwhera","interest.lede":"Kei te pre-alpha kati a AI-gile. Waihotia tō īmēra, ā, ka tuhi atu mātou kotahi anake, ina whai wāhi koe.","interest.email":"Tō īmēra","interest.which":"Tēhea whakamātautau?","interest.alpha":"Alpha kati: tōmua, taratara, he maha ngā panoni","interest.beta":"Beta: kua pūmau ake, mō muri","interest.both":"Tētahi, ko tēhea te tuatahi","interest.submit":"Tāpiritia ahau ki te rārangi","interest.thanks":"Ngā mihi! Kei te rārangi koe.","licence.title":"AI-gile: raihana pakihi","licence.description":"E whakamahi ana i a AI-gile i tō pakihi? Tonoa he raihana pakihi koreutu.","licence.h1":"📜 Raihana pakihi","licence.lede":"E whakamahi ana i a AI-gile i te mahi? Kōrerotia mai ko wai koe, he aha tāu mahi. Mēnā he painga tāna, he koreutu te raihana.","licence.company":"Kamupene","licence.website":"Pae tukutuku","licence.what":"Tāu mahi","licence.how":"Tōna āwhina ki te ao","licence.email":"Īmēra","licence.submit":"Tono","licence.thanks":"Ngā mihi! Ka whakautu atu mātou mā te īmēra.","status.title":"Tūnga o AI-gile","status.h1":"Tūnga o AI-gile","status.quiet":"Kāore he raruraru","status.checking":"E tirotiro ana…","status.offline":"Kāore e taea te toro ki te ratonga tūnga i tēnei wā (e whakamātau anō ana)","status.updated":"i whakahoutia {ago}","status.justNow":"inaianei tonu","status.min":"{n} meneti ki muri","status.hours":"{n} hāora ki muri","status.days":"{n} rā ki muri","live.h2":"Matakitaki i tana hanganga, ora","live.caption":"Kua huna ia kāri katoa: ka kite koe i te āhua o te mahi, kaua ko ngā kupu.","live.watching.one":"ora: {n} e matakitaki ana","live.watching.other":"ora: {n} e matakitaki ana","live.offline":"Kei te okioki paku te papa ora. Hoki mai a muri nei.","live.cols":"Backlog|Hei mahi|E mahi ana|E arotakengia ana e te rōpū|Māu e test|Mā te rōpū|Oti","live.last.now":"I nekehia te kāri whakamutunga inaianei tonu","live.last.min.one":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.min.other":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.hour.one":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.hour.other":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.day.one":"I nekehia te kāri whakamutunga {n} rā kua pahure","live.last.day.other":"I nekehia te kāri whakamutunga {n} rā kua pahure"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Karetao.","Tukuna."]},{"n":2,"texts":["Kanban karetao.","Whakaaro, hangaia.","Mahi tukuna."]},{"n":3,"texts":["Kanban mō karetao.","Whakaaro hei āhuatanga.","Kanban kaiwhakahaere koreutu."]},{"n":5,"texts":["Papa kanban, ngā kaiwhakahaere hanga.","Tuhia ngā kāri. Hangaia e rātou.","Koreutu, ā-rorohiko, kua whakamātauria, āhua porangi."]},{"n":8,"texts":["He papa kanban koreutu e mahi ai ngā kaiwhakahaere AI.","Tuhia he whakaaro. Ka hangaia e ngā kaiwhakahaere. Whakaaetia.","Agile mō te tangata kotahi me te tini karetao manawanui."]},{"n":13,"texts":["He papa kanban i tō rorohiko e tango ai ngā kaiwhakahaere AI i ngā kāri.","Tuhia he whakaaro. Ka hangaia e tētahi rōpū kaiwhakahaere. Ka tirotirohia e tētahi kaiwhakamātau.","Kāore he kāute, kāore he kaiwhai: he papa, he karetao, ā, ko koe te rangatira."]},{"n":21,"texts":["He papa kanban a AI-gile hei mahi tahi ki ngā kaiwhakahaere waehere AI. Ka tango rātou i ngā kāri; mā koe e whakamātau, e whakaae.","He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiri kōrero ki tētahi kāri, ka tīmata te rōpū ki te mahi.","He papa mahi tūmataiti, koreutu, e rere ana i tō rorohiko. Ko ngā kaimahi he karetao. Ko koe te kaiwhakaae."]},{"n":34,"texts":["Ka whakatakotoria e koe ngā whakaaro ki te papa. Ka huria e tētahi rōpū kaiwhakahaere AI hei āhuatanga e mahi ana, ka whakamātauria, ka hoatu me ngā hikoi hei whakamātau. Kāore he mea e oti kia kore koe e kī.","He papa kanban i hangaia ā-ringa e Rich, me te āwhina nui a ngā kaiwhakahaere e whakahaerehia ana e ia inaianei. He koreutu, e rere ana i tō rorohiko, ā, ka tukua ki ngā hoa, ehara i te hoko.","Whakaarohia he papa kanban, he pou mai i te Backlog ki te Oti, engari ko ngā kaiwhakahaere AI ngā kaitango i ngā kāri. Ka kōrero rātou mō te ahunga whakamua, ka pātai ina piri, ā, ka tatari ki tō tohu pai."]},{"n":55,"texts":["He papa kanban a AI-gile e mahi ai ngā kaiwhakahaere AI hei rōpū. He kaihautū tō ia kaupapa hei whakamahere i te mahi, me ngā kaiāwhina hei hanga. Ina rite tētahi āhuatanga, ka whakamātauria e te kaiwhakamātau AI, ka tango tānga mata, ā, ka tae ki tō puranga. Whakaaetia, kōrerotia rānei, ā, ka mahi anō rātou.","I tīmata mai hei huarahi mā tētahi tangata ki te aroturuki i te maha o ngā wā mahi waehere AI i te wā kotahi, ā, i tupu hei papa tika. Ka rere i tō rorohiko, kāore he kāute e hiahiatia, kāore he kaiwhai. He koreutu mō ngā hoa me te hunga hihiri. Kāore anō kia oti, ka kitea ētahi tapa taratara me tētahi ohorere.","Anei te putanga pono. Māu tonu e whakaaro ngā whakaaro, māu tonu e tirotiro ngā putanga. Ko te mahi a AI-gile ko ngā mea katoa kei waenganui: ka tiaki i ngā kāri kia tōtika, ka whakaoho i te kaiwhakahaere tika ina kōrero koe, ka whakaatu he aha te mea kua rerekē, ka whakahaere i te katoa ki tētahi puranga poto mōu."]},{"n":89,"texts":["He papa kanban koreutu a AI-gile e rere ana i tō ake rorohiko. Hei utu mō ngā tāngata, he rōpū kaiwhakahaere AI tō ia kaupapa: he kaihautū hei huri i ō whakaaro hei kāri me tētahi mahere, me ngā kaiāwhina hei tango i ngā kāri i te raupapa matua. Ina oti tētahi mea te hanga, ka whai te kaiwhakamātau AI i ngā hikoi whakamātau, ka whakaatu i tāna i kite ai. Kātahi ka tatari ki roto i tētahi puranga e kīia ana Māu. Whakaaetia, kōrerotia rānei, ā, ka whakamātau anō te rōpū. Kāore he mea e tae ki Oti ki te kore koe.","Ētahi āhuatanga kāore pea koe e tūmanako. Ka whakakī te kaitiaki pō i te pou Hei mahi i a koe e moe ana, mā te kōwhiri i ngā kāri kāore e hiahia ana ki tō whakautu. Ka whakaatu te kaiwhakatatau tohu i te nui o tā ngā kaiwhakahaere whakamahi i tēnei rā, i tēnei wiki hoki. Ka taea e koe te tuku karere ki ngā hoa, ā, he hunahuna ngā karere tūmataiti mai i tētahi pito ki tētahi. E kōrero ana te papa i te 120 reo, tae atu ki te Tati, te kaipahua me te Klingon. Kāore tētahi o ēnei e utu moni.","He kaupapa iti, whaiaro a AI-gile, ehara i te kamupene. I hiahia a Rich ki te tiaki i ētahi kaupapa waehere AI me te kore e whakatuwhera i ia taupānga hei tirotiro, nā reira ka hangaia e ia me ngā kaiwhakahaere he papa mō tērā, ā, ka whakamahia taua papa ki te hanga i te toenga o ia ake. Kei te pre-alpha kati, arā, ka mahi, te nuinga o te wā, mō ētahi hoa torutoru. Kāore he whārangi utu, kāore he pānuitanga, kāore he mahere tipu. Mēnā he whai take, ka taea e koe te tono kia whakamātau ina tuwhera whānui ake."]},{"n":144,"texts":["He papa kanban a AI-gile mō tētahi tangata me te tini o ngā kaiwhakahaere AI. Ka rere i tō ake rorohiko, ā, he koreutu rawa. Ka kōrero koe ki te kaihautū, pērā i a Discord, ka whakaahua i tētahi whakaaro; ka huri te kaihautū hei kāri me tētahi mahere, ā, ka tatari kia pēhia e koe te Haere. Ka mahi te rōpū i ngā kāri i te raupapa matua, mā tētahi rārangi whakahau ngāwari i hangaia mō ngā tauira reo. I mua i te hokinga mai ki a koe, ka whai te kaiwhakamātau AI i ngā hikoi i runga i tētahi kape o te taupānga, ka tāpiri i tētahi tānga mata. Ka tae te mahi kua oti ki tō puranga me ngā kōnae kua rerekē me te rerekētanga. Ka whakaae koe, ka waiho rānei he kōrero, ā, ka oho te rōpū, ka whakamātau anō. Ko koe anake e taea te nuku i tētahi kāri ki Oti.","Anei te āhua o tētahi rā me AI-gile. I te ahiahi ka waiho e koe ētahi kōrero: kei te wāhi hē tēnei pātene, me whakarōpū tērā rārangi, me whai aratau pōuri pea. Ka haere koe ki te moe. Ka pānui ngā kaiwhakahaere i ngā kōrero, ka whakarerekē, ka whakamātau, ka hoatu anō ki a koe. Mēnā ka maroke te Hei mahi, ka whakakī te kaitiaki pō i a ia mai i te backlog ki ngā kāri kāore e hiahia ana ki tō whakautu. I te ata he puranga poto kotahi: tētahi rua pātai me ētahi mea hei whakamātau, tēnā me tēnā me ngā hikoi e taea e te tangata ngenge, me tētahi tānga mata e whakaatu ana kei te mahi. Ka pāwhiri koe, ka whakaae i ngā mea pai, ka whakahoki i te toenga. Ka whakaatu te kaiwhakatatau tohu i te nui o te pau, ā, kei reira te Aratau Kore Tohu mō ngā wiki kōmaki. Kātahi koe ka kai parakuihi, kāore anō kia taea e ngā kaiwhakahaere te āwhina.","Tuatahi, ehara a AI-gile i te aha. Ehara i te kamupene hōu, ehara i te mea e hokona ana, ā, kāore he tangata e kohi ana i ō raraunga. He papa koreutu e rere ana i tō rorohiko, kāore he kāute, kāore he kaiwhai, kāore he pihikete. Ko te mea ia: kotahi te wāhi tōtika hei tiro i ngā kaupapa waehere AI katoa i te wā kotahi, ko tētahi rōpū kaiwhakahaere e mahi ana i ngā kāri, ā, māu ngā whakatau. E kōrero ana i te 120 reo, mai i te Tati ki te kaipahua me te Klingon. I hangaia e Rich me te tini o ngā kaiwhakahaere manawanui, te nuinga mā te whakamahi i a ia ake. Kei te pre-alpha kati, nō reira he taratara ētahi wāhi. Mēnā he hākinakina, pātai atu i runga i te mihi, ā, tērā pea ka uru wawe koe."]}],"quips":{"1":"Kotahi te kupu. Pakari. Tērā pea he nui rawa te pakari.","3":"E toru ngā kupu. Kua pono ake i te nuinga o ngā whārangi hua.","8":"E waru ngā kupu. He poto tonu i tētahi stand-up.","21":"He tohu kōrero ngā roa, nā. Ae rā.","55":"E rima tekau mā rima ngā kupu. E rua ngā kāri i oti i a koe e pānui ana.","144":"Koinei te mea roa. Kāore he 233. Kua haere ngā kaiwhakahaere ki te moe."}},"timeline":{"first-idea.name":"Te whakaaro tuatahi","first-idea.line":"Te kōrero tuatahi rawa, i mua i te whai waehere.","first-board.name":"Te papa tuatahi","first-board.line":"He papa e whai ana i tōna ake hanga: ngā kāri, ngā pou, te toia, ngā kaupapa.","team-roles.name":"Te rōpū me ngā tūranga","team-roles.line":"Ngā kōtaha kaiwhakahaere, ngā tauira rōpū, ngā mokowā me te mahi a ia tangata.","install.name":"Te tāuta me ngā tukunga","install.line":"He zip e taea e tētahi hoa te tāuta, te whakahou-ā-tinana, ngā hongere me te hoki whakamuri.","usage-saver.name":"Te kaitiaki whakamahinga","usage-saver.line":"Ine i te utu o ngā whakahaerenga, kia kōmaki te waehere, kia mau tō tepe.","friends.name":"Ngā hoa me te tiritiri","friends.line":"Ngā karere tūmataiti, he hononga hunahuna, ngā pōwhiri, ngā tūranga me ngā kaupapa tiritahi.","languages.name":"Ngā reo","languages.line":"Ia kupu o ia mata i tētahi kōnae reo, ko te Tati tuatahi.","ai-tester.name":"Kaiwhakamātau AI","ai-tester.line":"Ka tirotiro tuatahi tētahi kaiwhakamātau i ia tukunga, ka whakaatu i tāna i kite ai.","website.name":"Te pae tukutuku","website.line":"aigile.lol, te whārangi tīmatanga me tēnei rārangi wā.","streaming.name":"Te kōrero me te rere ora","streaming.line":"Discord, Twitch, OBS, te aratau kaiwhakaatu, ngā GIF me ngā emoji.","no-ai.name":"Te putanga kore AI","no-ai.line":"He papa mō te hunga e waehere ana me te kore AI, me ngā papa tūmatanui.","night-watch.name":"Te kaitiaki pō","night-watch.line":"Ka whakahaere tētahi kaitiaki me tētahi Scrum Master i ngā rōpū i a koe e moe ana.","p-more.name":"Ngā mea katoa atu","p-more.line":"Ngā whakaaro iti e tatari tonu ana i tō rātou wā.","p-android.name":"Te waea me Android","p-android.line":"Toro atu ki tō papa mai i te waea, kātahi he taupānga Android ake.","p-release.name":"Te alpha me tua atu","p-release.line":"Te alpha kati, te pae ora, kātahi te beta.","p-languages.name":"Ētahi atu reo","p-languages.line":"Neke atu i te rau ngā reo, me tētahi aratau rumaki mā ngā ākonga.","p-engines.name":"Ētahi atu pūkaha AI","p-engines.line":"Kōwhiria a Claude, Codex, Gemini rānei mō ia kaiwhakahaere.","p-pro.name":"Te tikanga ngaio","p-pro.line":"Ngā tūtohu tūpono, ngā kēti whakakotahi, ngā kāri aituā me ngā tiaki.","p-self.name":"Te tiaki i a koe","p-self.line":"Te aratau ngenge, ngā whakamahara tiaki-whaiaro me te 4:20.","p-servers.name":"Ngā tūmau me te whānui","p-servers.line":"Ngā tautuhinga tūmau ao, ngā tūranga me te whakamahere mō te tipu.","p-livestream.name":"Ngā taapiri rere ora","p-livestream.line":"Te kōrero Twitch, ngā emoji ake me tētahi tirohanga ora tūmatanui."}};
